/** design-lint — generated by AGILER; do not edit.
 *
 * Screens must compose @agiler/ui components only, and carry no presentation of their own.
 * Runs as part of `npm run build`, so a violation fails the order's CI too.
 */
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative, sep } from 'node:path';

const SCREEN_DIR = 'src/screens';
const ALLOWED = ['@agiler/ui', '../scaffold', './'];
const RULES = [
  { name: 'import', re: /from\s+'([^']+)'/g, validate: (m) => !ALLOWED.some((p) => m[1].startsWith(p)),
    message: (m) => `imports '${m[1]}' — only @agiler/ui and the scaffold are allowed` },
  { name: 'inline-style', re: /(?<![\w-])style\s*=/g, message: () => 'sets an inline style' },
  { name: 'class-name', re: /(?<![\w-])className\s*=/g, message: () => 'sets className' },
  { name: 'hex-colour', re: /#[0-9a-fA-F]{3,8}\b/g, message: (m) => `contains the hex colour ${m[0]}` },
];

const walk = (dir) => {
  let files = [];
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    files = statSync(full).isDirectory() ? [...files, ...walk(full)] : [...files, full];
  }
  return files;
};

const problems = [];
for (const file of walk(SCREEN_DIR)) {
  if (!file.endsWith('.tsx') && !file.endsWith('.ts')) continue;
  const source = readFileSync(file, 'utf8');
  for (const rule of RULES) {
    for (const match of source.matchAll(rule.re)) {
      if (rule.validate && !rule.validate(match)) continue;
      problems.push(`${relative(process.cwd(), file).split(sep).join('/')} ${rule.message(match)}`);
    }
  }
}

if (problems.length > 0) {
  console.error('design-lint failed:');
  for (const problem of problems) console.error(`  - ${problem}`);
  process.exit(1);
}
console.log('design-lint: screens are on the design system.');
